#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/ztest.h>
#include <string.h>

#define MAX_INIT_LEVEL_DEVICES 5
static const struct device *init_sequence[MAX_INIT_LEVEL_DEVICES];
static int init_count;

static int init_level_dummy_init_func(const struct device *dev)
{
    if (init_count < MAX_INIT_LEVEL_DEVICES) {
        init_sequence[init_count++] = dev;
    }
    return 0;
}

// Define devices for test_device_init_level with distinct levels and priorities
DEVICE_DEFINE(dev_pre_k1_0, "pre_k1_0", init_level_dummy_init_func, NULL, NULL, NULL, PRE_KERNEL_1, 0);
DEVICE_DEFINE(dev_pre_k1_1, "pre_k1_1", init_level_dummy_init_func, NULL, NULL, NULL, PRE_KERNEL_1, 1); // Priority 1 to ensure order
DEVICE_DEFINE(dev_pre_k2_0, "pre_k2_0", init_level_dummy_init_func, NULL, NULL, NULL, PRE_KERNEL_2, 0);
DEVICE_DEFINE(dev_post_k_0, "post_k_0", init_level_dummy_init_func, NULL, NULL, NULL, POST_KERNEL, 0);
DEVICE_DEFINE(dev_app_0, "app_0", init_level_dummy_init_func, NULL, NULL, NULL, APPLICATION, 0);

// --- Device definitions for other tests ---

// For test_deinit_not_supported
static int deinit_not_supported_init(const struct device *dev) { return 0; }
DEVICE_DEFINE(deinit_not_supported_dev, "deinit_not_supported", deinit_not_supported_init, NULL, NULL, NULL, POST_KERNEL, 0);

// For test_deinit_success_and_redeinit
static int deinit_success_init(const struct device *dev) { return 0; }
static int deinit_success_deinit(const struct device *dev) { return 0; } // Defined before use
DEVICE_DEFINE(deinit_success_dev, "deinit_success", deinit_success_init, deinit_success_deinit, NULL, NULL, NULL, POST_KERNEL, 0);

// For test_device_api
static int api_init(const struct device *dev) { return 0; }
DEVICE_DEFINE(api_dev, "api_dev", api_init, NULL, NULL, NULL, POST_KERNEL, 0);

// For test_device_api_extends, etc.
struct parent_api {
    void (*func)(void);
};
struct child_api {
    struct parent_api parent;
    void (*child_func)(void);
};
static void parent_func(void) {}
static void child_func(void) {}
static int parent_dev_init(const struct device *dev) { return 0; }
static int child_dev_init(const struct device *dev) { return 0; }
static const struct parent_api parent_api_impl = { .func = parent_func };
static const struct child_api child_api_impl = { .parent = { .func = parent_func }, .child_func = child_func };

DEVICE_DEFINE(parent_dev, "parent_dev", parent_dev_init, NULL, &parent_api_impl, NULL, POST_KERNEL, 0);
DEVICE_DEFINE(child_dev, "child_dev", child_dev_init, NULL, &child_api_impl, NULL, POST_KERNEL, 0);
DEVICE_DEFINE(grandchild_dev, "grandchild_dev", child_dev_init, NULL, &child_api_impl, NULL, POST_KERNEL, 0);
DEVICE_DEFINE(sibling_dev, "sibling_dev", child_dev_init, NULL, &child_api_impl, NULL, POST_KERNEL, 0);


ZTEST_SUITE(device_api, NULL, NULL, NULL, NULL, NULL);

ZTEST(device_api, test_deinit_not_supported)
{
    const struct device *dev = DEVICE_GET(deinit_not_supported_dev);
    zassert_not_null(dev, "Device not found");
    zassert_equal(-ENOTSUP, device_deinit(dev), "Expected -ENOTSUP for deinit");
}

ZTEST(device_api, test_deinit_success_and_redeinit)
{
    const struct device *dev = DEVICE_GET(deinit_success_dev);
    zassert_not_null(dev, "Device not found");
    zassert_equal(0, device_deinit(dev), "Expected successful deinit");
    zassert_equal(0, device_init(dev), "Expected successful re-init");
}

ZTEST(device_api, test_device_api)
{
    const struct device *dev = DEVICE_GET(api_dev);
    zassert_not_null(dev, "Device not found");
}

ZTEST(device_api, test_device_api_extends)
{
    const struct device *dev = DEVICE_GET(child_dev);
    zassert_not_null(dev, "Child device not found");
    const struct child_api *api = (const struct child_api *)dev->api;
    zassert_not_null(api, "Child device API is NULL");
    api->parent.func(); // Call parent function
    api->child_func();  // Call child function
}

ZTEST(device_api, test_device_api_extends_grandchild)
{
    const struct device *dev = DEVICE_GET(grandchild_dev);
    zassert_not_null(dev, "Grandchild device not found");
    const struct child_api *api = (const struct child_api *)dev->api;
    zassert_not_null(api, "Grandchild device API is NULL");
    api->parent.func();
    api->child_func();
}

ZTEST(device_api, test_device_api_extends_sibling)
{
    const struct device *dev = DEVICE_GET(sibling_dev);
    zassert_not_null(dev, "Sibling device not found");
    const struct child_api *api = (const struct child_api *)dev->api;
    zassert_not_null(api, "Sibling device API is NULL");
    api->parent.func();
    api->child_func();
}

ZTEST(device_api, test_device_init_level)
{
    // The devices are initialized by the kernel before ztest runs.
    // We just need to verify the recorded sequence.

    const struct device *expected_sequence[] = {
        &dev_pre_k1_0,
        &dev_pre_k1_1,
        &dev_pre_k2_0,
        &dev_post_k_0,
        &dev_app_0,
    };
    int expected_count = ARRAY_SIZE(expected_sequence);

    bool seq_correct = true;

    if (init_count != expected_count) {
        seq_correct = false;
    } else {
        for (int i = 0; i < expected_count; i++) {
            if (init_sequence[i] != expected_sequence[i]) {
                seq_correct = false;
                break;
            }
        }
    }

    zassert_true(seq_correct, "Device initialization sequence is incorrect");
}
